windowclass.script:
function onInit()
	self.onLockModeChanged(WindowManager.getWindowReadOnlyState(self));
	onDiceChanged();
end

function onLockModeChanged(bReadOnly)
	local tFields = { "craft",
		"type",
		"scale",
		"length",
		"skill",
		"skillspecialty",
		"crew",
		"crewskill",
		"cargo",
		"consumables",
		"cost",
		"hyperdrive",
		"hyperdrivebackup",
		"navcomputer",
		"maneuverability",
		"space",
		"atmosphere",
		"hull",
		"shields",
		"sensorpassive",
		"sensorscan",
		"sensorsearch",
		"sensorfocus",
		"weaponscale",
		"weaponcrew",
		"notes", };
	WindowManager.callSafeControlsSetLockMode(self, tFields, bReadOnly);
	divider2.setVisible(WindowManager.getAnyControlVisible(self, { "type", }));
	divider3.setVisible(WindowManager.getAnyControlVisible(self, { "notes", }));
end

function onDiceChanged()
	local bMShow = not mdice.isEmpty();
	mdice.setVisible(bMShow);
	mbutton_roll.setVisible(bMShow);

	local bHShow = not hdice.isEmpty();
	hdice.setVisible(bHShow);
	hbutton_roll.setVisible(bHShow);

	local bSShow = not sdice.isEmpty();
	sdice.setVisible(bSShow);
	sbutton_roll.setVisible(bSShow);

	local bSensorPassiveShow = not spdice.isEmpty();
	spdice.setVisible(bSensorPassiveShow);
	spbutton_roll.setVisible(bSensorPassiveShow);

	local bSensorScanShow = not ssdice.isEmpty();
	ssdice.setVisible(bSensorScanShow);
	ssbutton_roll.setVisible(bSensorScanShow);

	local bSensorSearchShow = not srdice.isEmpty();
	srdice.setVisible(bSensorSearchShow);
	srbutton_roll.setVisible(bSensorSearchShow);

	local bSensorFocusShow = not sfdice.isEmpty();
	sfdice.setVisible(bSensorFocusShow);
	sfbutton_roll.setVisible(bSensorFocusShow);			
end

function onDrop(x, y, draginfo)
	local sDragType = draginfo.getType();
	if sDragType == "dice" then
		local aDropDice = draginfo.getDiceData();
		sDropDesc = draginfo.getDescription();
		for _,vDie in ipairs(aDropDice) do
			if sDropDesc:find("maneuverability") then
				Debug.console("adding maneuverability");
				mdice.addDie(vDie.type);
			elseif sDropDesc:find("hull") then
				Debug.console("adding hull");
				hdice.addDie(vDie.type);
			elseif sDropDesc:find("shields") then
				Debug.console("adding shields");
				sdice.addDie(vDie.type);
			elseif sDropDesc:find("passive") then
				Debug.console("adding sensor passive");
				spdice.addDie(vDie.type);
			elseif sDropDesc:find("scan") then
				Debug.console("adding sensor scan");
				ssdice.addDie(vDie.type);
			elseif sDropDesc:find("search") then
				Debug.console("adding sensor search");
				srdice.addDie(vDie.type);
			elseif sDropDesc:find("focus") then
				Debug.console("adding sensor focus");
				sfdice.addDie(vDie.type);
			end
		end
		return true;
	end
end

function action(draginfo)
	local sLabel = maneuverability_label.getValue();
	local aDice = mdice.getDice();
	local nMod = mbonus.getValue();

	if mdice.isEmpty() then
		if draginfo then
			draginfo.setType("number");
			draginfo.setDescription(sLabel);
			draginfo.setStringData(sLabel);
			draginfo.setNumberData(nMod);
		else
			ModifierStack.addSlot(sLabel, nMod);
		end
	else
		local rRoll = { sType = "dice", sDesc = sLabel, aDice = aDice, nMod = nMod };
		ActionsManager.performAction(draginfo, nil, rRoll);
	end
	return true;
end

